// Learn: short cards on what research says about speaking, charisma, body language and conversation (see documents/plan-learn.md)

// How strong the evidence behind a card is
export type Evidence = "strong" | "moderate" | "mixed" | "myth" | "practical";

// The words shown for each evidence label (never colour alone)
export const EVIDENCE_LABELS: Readonly<Record<Evidence, string>> = {
  // Replicated, or a large review
  strong: "Strong evidence",
  // A good study or two
  moderate: "Moderate evidence",
  // Studies disagree
  mixed: "Mixed evidence",
  // Popular, but not supported
  myth: "A myth",
  // Practical advice, not a research finding
  practical: "Practical advice",
};

// The kinds of card
export type CardKind = "explainer" | "myth-or-fact" | "try-it";

// The sets of cards
export type LearnSetId = "nerves" | "charisma" | "body" | "conversation" | "warmth" | "stories" | "practice" | "voice" | "point" | "minds" | "hard";

// One set: its name and a line on what it covers
export const LEARN_SETS: ReadonlyArray<{ id: LearnSetId; name: string; blurb: string }> = [
  // Speaking nerves
  { id: "nerves", name: "Nerves and presence", blurb: "What your audience really notices." },
  // Charisma
  { id: "charisma", name: "Charisma", blurb: "What it is, and the parts you can practise." },
  // Body language
  { id: "body", name: "Body language: myth or fact", blurb: "What holds up, and what does not." },
  // Conversation
  { id: "conversation", name: "Conversation", blurb: "Asking, listening, and how talks really go." },
  // Warmth and connection (decision 54)
  { id: "warmth", name: "Warmth and connection", blurb: "The small moves that make people feel heard." },
  // Stories
  { id: "stories", name: "Stories you can tell", blurb: "Turning ordinary days into something to tell." },
  // How practice works
  { id: "practice", name: "How to practise", blurb: "Why VoiceLab works the way it does." },
  // Your voice (decision 71)
  { id: "voice", name: "Your voice", blurb: "Pace, pitch and pauses, and how listeners hear them." },
  // Getting your point across
  { id: "point", name: "Getting your point across", blurb: "Say it so it lands, and answer what was asked." },
  // Changing minds
  { id: "minds", name: "Changing minds", blurb: "Honest ways to persuade." },
  // Hard conversations
  { id: "hard", name: "Hard conversations", blurb: "Disagreeing, apologising and asking." },
];

// The sets in two groups on the Learn page, so eleven sets do not read as one long list (decision 79): speaking to a room, and being with people
export const LEARN_GROUPS: ReadonlyArray<{ name: string; sets: ReadonlyArray<LearnSetId> }> = [
  // Speaking: nerves, voice, getting the point across, stories, and how practice works
  { name: "Speaking", sets: ["nerves", "voice", "point", "stories", "practice"] },
  // People: charisma, body language, conversation, warmth, persuasion and hard talks
  { name: "People", sets: ["charisma", "body", "conversation", "warmth", "minds", "hard"] },
];

// A myth-or-fact card's verdict
export type Verdict = "myth" | "fact" | "mixed";

// One card
export interface LearnCard {
  // Stable id
  id: string;
  // Its set
  set: LearnSetId;
  // Its kind
  kind: CardKind;
  // The question or belief it starts from, set like a headline
  title: string;
  // For a myth-or-fact card: the verdict the guess is checked against
  verdict?: Verdict;
  // What the research found, in two or three plain sentences
  finding: string;
  // What it means, in one or two lines
  meaning: string;
  // What to do, in one or two lines
  doThis: string;
  // For a try-it card: a short exercise to say aloud on the card
  exercise?: string;
  // A link to practise it, if there is one
  tryIt?: { label: string; href: string };
  // The one line to remember (shown again after a wrong recall, and used for saying it back)
  keyLine: string;
  // The recall question, with its options and the right one
  recall: { question: string; options: ReadonlyArray<string>; answer: number };
  // How strong the evidence is
  evidence: Evidence;
  // The source, in short form, and where to read it
  source: { text: string; url?: string };
  // A small step to try for real, away from the app (decision 71)
  outThere?: string;
  // A scenario to choose the best reply in, then say it aloud (ids from src/content/scenarios.ts)
  scenario?: string;
}

// Every card, set by set
